import { useState } from "react";
import CoursePage from "./pages/CoursePage";
import AssessmentPage from "./pages/AssessmentPage";
import VideoPage from "./pages/VideoPage";
import { generateAssessment, checkAssessment, checkSimilarity } from "./api";

function App() {
  // Existing app stages
  const [stage, setStage] = useState("course"); // "course" | "assessment" | "video"
  const [course, setCourse] = useState(null);
  const [questions, setQuestions] = useState(null);
  const [result, setResult] = useState(null);
  const [points, setPoints] = useState(0);

  // New Teach & Earn flow toggle
  const [showTeachFlow, setShowTeachFlow] = useState(true); // default to preview the new UI

  if (showTeachFlow) {
    return <TeachFlow onExit={() => setShowTeachFlow(false)} />;
  }

  const stages = ["course", "assessment", "video", "complete"];

  return (
    <div style={{ padding: "2rem" }}>
      {/* Stepper UI */}
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "2rem" }}>
        {stages.map((s, idx) => (
          <div key={s} style={{ flex: 1, textAlign: "center" }}>
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: "50%",
                background: stage === s ? "#2563eb" : "#d1d5db",
                color: "white",
                margin: "0 auto",
                lineHeight: "40px",
              }}
            >
              {idx + 1}
            </div>
            <p>{s.toUpperCase()}</p>
          </div>
        ))}
      </div>

      {/* Stage Content */}
      {stage === "course" && (
        <div style={{ padding: 24 }}>
          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 12 }}>
            <button onClick={() => setShowTeachFlow(true)} style={btnSecondary}>
              Open Teach & Earn
            </button>
          </div>
          <CoursePage
            setCourse={setCourse}
            setQuestions={setQuestions}
            setStage={setStage}
          />
        </div>
      )}

      {stage === "assessment" && (
        <AssessmentPage
          questions={questions}
          course={course}
          setResult={setResult}
          setStage={setStage}
        />
      )}

      {stage === "video" && (
        <VideoPage
          course={course}
          onSuccess={(score) => {
            if (score >= 0.7) {
              setPoints((prev) => prev + 100);
              setStage("complete");
            } else {
              alert("Similarity too low. Please try again.");
            }
          }}
        />
      )}

      {stage === "complete" && (
        <div style={{ textAlign: "center" }}>
          <h2>✅ Video successfully uploaded!</h2>
          <p>You earned <b>{points}</b> points 🎉</p>
          <button onClick={() => setStage("course")}>Back to Dashboard</button>
        </div>
      )}
    </div>
  );
}

// -----------------------------
// Teach & Earn (Teach a Course)
// -----------------------------
function TeachFlow({ onExit }) {
  const [step, setStep] = useState(1); // 1: Course Info, 2: Knowledge Test, 3: Upload Video, 4: Complete
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [courseName, setCourseName] = useState("");
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [similarityScore, setSimilarityScore] = useState(null);
  const [file, setFile] = useState(null);

  const threshold = 0.7; // similarity threshold for publishing

  const goDashboard = () => onExit?.();

  const handleGenerateAssessment = async () => {
    setError("");
    if (!courseName.trim()) {
      setError("Please enter a course name.");
      return;
    }
    try {
      setLoading(true);
      const res = await generateAssessment(courseName.trim());
      if (res?.questions && Array.isArray(res.questions) && res.questions.length) {
        setQuestions(res.questions);
        setAnswers(new Array(res.questions.length).fill(""));
        setStep(2);
      } else if (res?.error) {
        setError("Assessment generation failed: " + res.error);
      } else {
        setError("Could not generate questions. Please try again.");
      }
    } catch (e) {
      setError("Server error while generating assessment.");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitAssessment = async () => {
    setError("");
    if (!questions.length) return;
    if (answers.some((a) => !a)) {
      setError("Please answer all questions.");
      return;
    }
    try {
      setLoading(true);
      const res = await checkAssessment(courseName, answers, questions);
      if (res?.result === "pass") {
        setStep(3);
      } else {
        setError(res?.message || "You must pass the assessment to proceed.");
      }
    } catch (e) {
      setError("Server error while checking assessment.");
    } finally {
      setLoading(false);
    }
  };

  const handleUploadVideo = async () => {
    setError("");
    if (!file) {
      setError("Please select a video file.");
      return;
    }
    try {
      setLoading(true);
      const res = await checkSimilarity(courseName, file);
      const score = typeof res?.similarity_score === "number" ? res.similarity_score : null;
      setSimilarityScore(score);
      if (score !== null && score >= threshold) {
        setStep(4);
      } else {
        setError("Similarity below threshold. Please review your video and try again.");
      }
    } catch (e) {
      setError("Server error while uploading video or computing similarity.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={pageWrap}>
      <div style={headerWrap}>
        <div style={iconBadge}>📘</div>
        <h1 style={{ margin: 8 }}>Teach a Course</h1>
        <p style={{ margin: 0, color: "#667085" }}>
          Share your knowledge and earn points by teaching courses to the community.
        </p>
      </div>

      <Stepper current={step} />

      {step === 1 && (
        <div style={card}>
          <h2 style={{ marginTop: 0 }}>What course would you like to teach?</h2>
          <label style={label}>Course Name</label>
          <input
            style={input}
            placeholder="e.g., Introduction to Database Management Systems"
            value={courseName}
            onChange={(e) => setCourseName(e.target.value)}
          />

          <div style={tipBox}>
            <b>What happens next?</b>
            <ul style={{ marginTop: 8 }}>
              <li>AI will generate an assessment to verify your knowledge</li>
              <li>You’ll need to pass this test to proceed</li>
              <li>Upload your teaching video</li>
              <li>Earn points based on course value and engagement</li>
            </ul>
          </div>

          {error && <div style={errorBox}>{error}</div>}

          <div style={{ display: "flex", gap: 12 }}>
            <button style={btnPrimary} onClick={handleGenerateAssessment} disabled={loading}>
              {loading ? "Generating..." : "Continue to Assessment"}
            </button>
            <button style={btnSecondary} onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div style={card}>
          <h2 style={{ marginTop: 0 }}>Knowledge Test</h2>
          <p style={{ color: "#667085" }}>Answer all questions correctly to proceed.</p>

          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            {questions.map((q, idx) => (
              <div key={idx} style={qBox}>
                <div style={{ marginBottom: 8 }}>
                  <b>Q{idx + 1}.</b> {q.question}
                </div>
                <div style={{ display: "grid", gap: 8 }}>
                  {q.options?.map((opt, oidx) => (
                    <label key={oidx} style={radioRow}>
                      <input
                        type="radio"
                        name={`q-${idx}`}
                        value={opt}
                        checked={answers[idx] === opt}
                        onChange={(e) => {
                          const v = e.target.value;
                          setAnswers((prev) => prev.map((p, i) => (i === idx ? v : p)));
                        }}
                      />
                      <span>{opt}</span>
                    </label>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {error && <div style={errorBox}>{error}</div>}

          <div style={{ display: "flex", gap: 12 }}>
            <button style={btnPrimary} onClick={handleSubmitAssessment} disabled={loading}>
              {loading ? "Checking..." : "Submit Answers"}
            </button>
            <button style={btnSecondary} onClick={() => setStep(1)}>Back</button>
            <button style={btnSecondary} onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div style={card}>
          <h2 style={{ marginTop: 0 }}>Upload Video</h2>
          <p style={{ color: "#667085" }}>
            Upload your course video. We'll compute how well it matches the course topic. A score ≥ {threshold}
            will be accepted and published to the public catalog.
          </p>

          <input
            type="file"
            accept="video/*"
            onChange={(e) => setFile(e.target.files?.[0] || null)}
            style={{ margin: "12px 0" }}
          />

          {typeof similarityScore === "number" && (
            <div style={infoBox}>Similarity Score: {similarityScore.toFixed(2)}</div>
          )}

          {error && <div style={errorBox}>{error}</div>}

          <div style={{ display: "flex", gap: 12 }}>
            <button style={btnPrimary} onClick={handleUploadVideo} disabled={loading}>
              {loading ? "Checking..." : "Upload & Check"}
            </button>
            <button style={btnSecondary} onClick={() => setStep(2)}>Back</button>
            <button style={btnSecondary} onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}

      {step === 4 && (
        <div style={card}>
          <h2 style={{ marginTop: 0 }}>Complete</h2>
          <div style={successBox}>
            ✅ Video successfully uploaded to the public catalog!
          </div>
          <div style={infoBox}>You earned 120 points for this course. Great job!</div>

          <div style={{ display: "flex", gap: 12 }}>
            <button style={btnPrimary} onClick={goDashboard}>Back to Dashboard</button>
          </div>
        </div>
      )}
    </div>
  );
}

// -----------------------------
// UI bits (inline styles)
// -----------------------------
const pageWrap = {
  padding: 24,
  minHeight: "100vh",
  background: "#F8FAFC",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
};

const headerWrap = {
  textAlign: "center",
  marginBottom: 16,
};

const iconBadge = {
  width: 56,
  height: 56,
  borderRadius: 16,
  background: "#EEF2FF",
  display: "inline-flex",
  alignItems: "center",
  justifyContent: "center",
  fontSize: 28,
};

const card = {
  width: "min(880px, 95%)",
  background: "white",
  border: "1px solid #E5E7EB",
  borderRadius: 12,
  padding: 20,
  boxShadow: "0 2px 8px rgba(16,24,40,0.05)",
};

const label = { display: "block", marginBottom: 6, color: "#344054" };

const input = {
  width: "100%",
  padding: "12px 14px",
  border: "1px solid #D0D5DD",
  borderRadius: 8,
  outline: "none",
  marginBottom: 12,
};

const tipBox = {
  background: "#F8FAFC",
  border: "1px solid #E2E8F0",
  padding: 12,
  borderRadius: 8,
  margin: "12px 0",
};

const infoBox = {
  background: "#EEF2FF",
  color: "#3730A3",
  border: "1px solid #E0E7FF",
  padding: 10,
  borderRadius: 8,
  margin: "12px 0",
};

const errorBox = {
  background: "#FEF2F2",
  color: "#991B1B",
  border: "1px solid #FECACA",
  padding: 10,
  borderRadius: 8,
  margin: "12px 0",
};

const successBox = {
  background: "#F0FDF4",
  color: "#166534",
  border: "1px solid #BBF7D0",
  padding: 10,
  borderRadius: 8,
  margin: "12px 0",
};

const btnPrimary = {
  background: "#2563EB",
  color: "white",
  padding: "10px 14px",
