function Stepper({ current }) {
  const steps = ["Course Info", "Knowledge Test", "Upload Video", "Complete"];
  return (
    <div style={{ display: "flex", gap: 12, margin: "12px 0 16px", flexWrap: "wrap" }}>
      {steps.map((label, idx) => {
        const n = idx + 1;
        const active = n === current;
        const done = n < current;
        return (
          <div key={n} style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <div
              style={{
                width: 28,
                height: 28,
                borderRadius: 999,
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                background: done ? "#10B981" : active ? "#2563EB" : "#E5E7EB",
                color: done || active ? "white" : "#374151",
                fontWeight: 600,
              }}
            >
              {n}
            </div>
            <div style={{ color: active ? "#111827" : "#6B7280", fontWeight: active ? 600 : 500 }}>{label}</div>
            {n !== steps.length && <div style={{ width: 24, height: 2, background: "#E5E7EB", margin: "0 6px" }} />}
          </div>
        );
      })}
    </div>
  );
}

